/**
 * Find province by MUHUZE ID.
 */
export function getProvinceById(
  provinceId: string
): RwandaProvince | undefined {
  return rwandaProvinces.find(
    (province) =>
      province.id === provinceId ||
      province.code === provinceId
  );
}

/**
 * Get districts belonging to a province.
 */
export function getDistrictsByProvinceId(
  provinceId: string
): RwandaDistrict[] {
  return (
    getProvinceById(provinceId)
      ?.districts ?? []
  );
}

/**
 * Find district.
 */
export function getDistrictById(
  provinceId: string,
  districtId: string
): RwandaDistrict | undefined {
  return getDistrictsByProvinceId(
    provinceId
  ).find(
    (district) =>
      district.id === districtId ||
      district.code === districtId
  );
}

/**
 * Get sectors belonging to a district.
 */
export function getSectorsByDistrictId(
  provinceId: string,
  districtId: string
): RwandaSector[] {
  return (
    getDistrictById(
      provinceId,
      districtId
    )?.sectors ?? []
  );
}

/**
 * Find sector.
 */
export function getSectorById(
  provinceId: string,
  districtId: string,
  sectorId: string
): RwandaSector | undefined {
  return getSectorsByDistrictId(
    provinceId,
    districtId
  ).find(
    (sector) =>
      sector.id === sectorId ||
      sector.code === sectorId
  );
}

/**
 * Get cells belonging to a sector.
 */
export function getCellsBySectorId(
  provinceId: string,
  districtId: string,
  sectorId: string
): RwandaCell[] {
  return (
    getSectorById(
      provinceId,
      districtId,
      sectorId
    )?.cells ?? []
  );
}

/**
 * Find cell.
 */
export function getCellById(
  provinceId: string,
  districtId: string,
  sectorId: string,
  cellId: string
): RwandaCell | undefined {
  return getCellsBySectorId(
    provinceId,
    districtId,
    sectorId
  ).find(
    (cell) =>
      cell.id === cellId ||
      cell.code === cellId
  );
}

/**
 * Get villages belonging to a cell.
 */
export function getVillagesByCellId(
  provinceId: string,
  districtId: string,
  sectorId: string,
  cellId: string
): RwandaVillage[] {
  return (
    getCellById(
      provinceId,
      districtId,
      sectorId,
      cellId
    )?.villages ?? []
  );
}
